  suborder shopping_mall_ai_order_suborders? @relation(fields: [shopping_mall_ai_order_suborder_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_order_state_logs_shopping_mall_ai_ord_dcd87925")
  admin shopping_mall_ai_administrators? @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)
