/// Payment commitment and settlement records for an order or suborder.
/// Tracks payment method, provider, status, financial breakdowns, and
/// references to related orders. Used for financial audits and
/// reconciliation with external processors.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_payments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to related order's {@link shopping_mall_ai_orders.id}.
  shopping_mall_ai_order_id String @db.Uuid

  /// Unique payment transaction code assigned by the platform.
  payment_code String

  /// Payment method at transaction (credit card, bank, mobile, deposit,
  /// mileage, etc.).
  payment_method String

  /// External payment processor or gateway name (as reported at time of
  /// settlement).
  payment_provider String

  /// Amount paid in this transaction.
  amount Float @db.DoublePrecision

  /// 3-letter ISO currency code (KRW, USD, etc.).
  currency String

  /// Payment status (pending, succeeded, failed, cancelled, etc.).
  status String

  /// Timestamp when payment was confirmed/approved (if completed).
  approved_at DateTime? @db.Timestamptz

  /// Timestamp of payment failure if failed/cancelled (nullable otherwise).
  failed_at DateTime? @db.Timestamptz

  /// Optional note or technical message for reconciliation/trace.
