schemas.schema-04-carts.prisma:
/// Represents a user's or guest's shopping cart session in the platform.
/// This model tracks all cart sessions, whether assigned to authenticated
/// customers or used anonymously by guests via device/session fingerprint.
/// Designed to support cart merging, abandonment recovery, real-time session
/// validation, and audit for business compliance. Maintains referential
/// integrity to customers (optional), tracks session tokens or device hashes
/// for unauthenticated carts, and holds expiration policy information. Key
/// relationships: optionally references a customer (for logged-in carts),
/// and connects via cart_items to every product selection. Cart merging,
/// concurrency events, and audit flow reference this table for traceability.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_ai_customers.id}. Nullable for
  /// guest/anonymous carts.
  shopping_mall_ai_customer_id String? @db.Uuid

  /// Hashed fingerprint of guest/anonymous browser/device session. For
  /// unauthenticated carts. Required when customer is null.
  device_session_hash String?

  /// Cart status such as active, expired, merged, or abandoned. Used to track
  /// cart lifecycle state for session and audit. Enforces valid cart state
  /// transitions.
  status String

  /// Date and time when this cart session expires due to inactivity. Cart is
  /// purged or archived after this time.
  expired_at DateTime? @db.Timestamptz

  /// Last time the cart was changed or accessed (add/remove item, update
  /// quantity, etc.). Used for session management, expiration, and customer
  /// engagement analytics.
  last_activity_at DateTime @db.Timestamptz

  /// Timestamp when cart session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when cart session was last updated (write lock, merge, edit,
  /// etc.).
  updated_at DateTime @db.Timestamptz

  /// When set, this cart has been logically deleted (soft delete for audit).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_cart_items                        shopping_mall_ai_cart_items[]
  shopping_mall_ai_cart_merge_logs_of_source_cart_id shopping_mall_ai_cart_merge_logs[] @relation("shopping_mall_ai_cart_merge_logs_of_source_cart_id")
  shopping_mall_ai_cart_merge_logs_of_target_cart_id shopping_mall_ai_cart_merge_logs[] @relation("shopping_mall_ai_cart_merge_logs_of_target_cart_id")

  @@unique([shopping_mall_ai_customer_id])
  @@index([device_session_hash])
  @@index([status])
  @@index([last_activity_at])
}

/// Stores each line item within a shopping cart, representing a selected
/// product, variant/option, and desired quantity. Ensures each
/// product+variant occurs only once per cart, supporting atomic item
/// operations and validity audit trails. References the cart, the product,
/// and the product_variant (for option-specific selection). Snapshot fields
/// enable audit of item-level changes. Actively excludes denormalized or
/// calculated values—only core selection data and temporal/audit fields are
/// present. Soft deletion supported for item removal tracking.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_cart_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent {@link shopping_mall_ai_carts.id} representing which cart this
  /// item belongs to. Not nullable.
  shopping_mall_ai_cart_id String @db.Uuid

  /// Referenced product's {@link shopping_mall_ai_products.id}.
  shopping_mall_ai_product_id String @db.Uuid

  /// Chosen variant's {@link shopping_mall_ai_product_variants.id}. Optionally
  /// set if the product uses variants.
  shopping_mall_ai_product_variant_id String? @db.Uuid

  /// Quantity of this line item in the cart. Must be positive; validated
  /// against product stock and business rules at the time of adding/updating.
  quantity Int @db.Integer

  /// Timestamp when this cart item was added. Used for auditing and session
  /// analytics.
  added_at DateTime @db.Timestamptz

  /// Timestamp when this cart item was last updated (quantity change, option
  /// change, etc.).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion marker for this item in the cart (item was removed before
  /// checkout or after merge).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart           shopping_mall_ai_carts             @relation(fields: [shopping_mall_ai_cart_id], references: [id], onDelete: Cascade)
  product        shopping_mall_ai_products          @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade)
  productVariant shopping_mall_ai_product_variants? @relation(fields: [shopping_mall_ai_product_variant_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_cart_items_shopping_mall_ai_product_v_a22aa485")

  @@unique([shopping_mall_ai_cart_id, shopping_mall_ai_product_id, shopping_mall_ai_product_variant_id], map: "shopping_mall_ai_cart_items_shopping_mall_ai_cart_id_s_0c342bc3")
  @@index([shopping_mall_ai_product_id])
  @@index([shopping_mall_ai_product_variant_id], map: "shopping_mall_ai_cart_items_shopping_mall_ai_product_v_87837142")
  @@index([shopping_mall_ai_cart_id])
  @@index([added_at])
}

/// Full audit trail for events where two shopping carts are merged—typically
/// during customer login (guest-to-customer), account linking, or session
/// restoration scenarios. Tracks both original cart ids, the resulting cart,
/// initiating actor/session, merge rationale, and pre/post merge status for
/// traceability. Supports compliance, customer support, and incident review.
/// Exclusively event/audit log; no calculated fields. All foreign keys
/// required for reconstructing merge lineage and forensics.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_cart_merge_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The original cart's {@link shopping_mall_ai_carts.id} that was merged
  /// into the target cart. Not nullable.
  source_cart_id String @db.Uuid

  /// The cart's {@link shopping_mall_ai_carts.id} that absorded/received the
  /// merge from the source cart. Not nullable.
  target_cart_id String @db.Uuid

  /// Optional customer's {@link shopping_mall_ai_customers.id} if the merge
  /// was triggered by a known authenticated user (e.g., logging in). Nullable
  /// for pure session/device-based merges.
  shopping_mall_ai_customer_id String? @db.Uuid

  /// Context or business reason for this cart merge event (e.g.,
  /// 'login_guest_to_auth', 'device_restore', 'manual_merge'). Supports audit
  /// trail, diagnosis, and behavior analytics.
  merge_context String

  /// Count of all items in source cart before merge (for auditing and
  /// forensics).
  pre_merge_item_count Int @db.Integer

  /// Item count in target cart after the merge operation.
  post_merge_item_count Int @db.Integer

  /// UTC timestamp when the merge event was finalized for audit traceability.
  merged_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  sourceCart shopping_mall_ai_carts      @relation("shopping_mall_ai_cart_merge_logs_of_source_cart_id", fields: [source_cart_id], references: [id], onDelete: Cascade)
  targetCart shopping_mall_ai_carts      @relation("shopping_mall_ai_cart_merge_logs_of_target_cart_id", fields: [target_cart_id], references: [id], onDelete: Cascade)
  customer   shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_cart_merge_logs_shopping_mall_ai_cust_139d1941")

  @@index([source_cart_id])
  @@index([target_cart_id])
  @@index([shopping_mall_ai_customer_id], map: "shopping_mall_ai_cart_merge_logs_shopping_mall_ai_cust_4e7ff121")
  @@index([merged_at])
}

