import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";

/**
 * 테스트 목적: 셀러 회원가입의 정상 처리와 이메일 중복 방지 검증
 *
 * 본 테스트는 신규 셀러가 정상적인 정보로 회원가입을 시도할 경우 성공적으로 토큰이 발급되고, 같은 이메일로 재시도할 경우 중복 이메일 오류가 발생하는지 검증합니다.
 *
 * 테스트 단계:
 * 1. 임의로 생성된 유효한 이메일, 비밀번호, 사업자 등록번호, 판매자명으로 셀러 회원가입을 시도합니다.
 *    - 성공적으로 회원가입이 처리되고 JWT 토큰이 setHeaders.Authorization에 포함되어 응답되는지 확인합니다.
 * 2. 동일한 이메일 주소를 사용하여 다시 셀러 회원가입을 시도합니다.
 *    - API가 이메일 중복 오류를 반환하는지, 신규 셀러 계정이 생성되지 않는지를 확인합니다.
 */
export async function test_api_seller_registration_success_and_duplicate_email(
  connection: api.IConnection,
) {
  // 1. 셀러 회원가입 정상 처리
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12); // 랜덤 12자리
  const business_registration_number = RandomGenerator.alphaNumeric(10); // 10자리, 실제 사업자번호 패턴 요구 시 수정 필요
  const display_name = RandomGenerator.name();

  const sellerResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password,
      business_registration_number,
      display_name,
    } satisfies ISellerAuthRegisterRequest,
  });
  typia.assert(sellerResponse);
  // JWT 토큰이 정상적으로 발급되고 셀러 정보가 올바르게 반환되는지 확인
  TestValidator.predicate("JWT 토큰이 발급됨")(typeof sellerResponse.setHeaders?.Authorization === "string" && sellerResponse.setHeaders?.Authorization.length > 0);
  TestValidator.equals("회원가입된 이메일 확인")(sellerResponse.seller.email)(email);
  TestValidator.equals("등록된 사업자등록번호 확인")(sellerResponse.seller.business_registration_number)(business_registration_number);
  TestValidator.equals("등록된 표시명 확인")(sellerResponse.seller.display_name)(display_name);

  // 2. 동일 이메일로 재가입 시도 -> 중복 오류 검증
  await TestValidator.error("중복 이메일로 회원가입 시도 시 오류 발생")(
    async () => {
      await api.functional.auth.seller.register.signUp(connection, {
        body: {
          email, // 동일 이메일로 시도
          password: RandomGenerator.alphaNumeric(12),
          business_registration_number: RandomGenerator.alphaNumeric(10),
          display_name: RandomGenerator.name(),
        } satisfies ISellerAuthRegisterRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";

/**
 * Validate seller registration with an invalid email format.
 *
 * In this test, we simulate an attempt to register a new seller account using an invalid email address (for example, omitting the '@' character or the domain). The API is expected to enforce email format validation and should reject the registration, returning a validation error and NOT creating the account.
 *
 * This E2E test ensures the system's registration endpoint correctly enforces basic email format requirements, preventing users from onboarding with malformed addresses.
 *
 * Steps:
 * 1. Attempt seller registration with an invalid email format (e.g., "invalid-email-format" without '@' or domain).
 * 2. Confirm that the registration fails and a validation error (type error) is thrown by the API.
 * 3. Ensure that no seller account is created as a result of this request.
 */
export async function test_api_seller_registration_invalid_email_format(
  connection: api.IConnection,
) {
  // 1. Attempt seller registration with invalid email format
  const invalidInput = {
    email: "invalid-email-format", // purposely missing '@' and domain
    password: "ValidPassw0rd!",
    business_registration_number: "123-45-67890",
    display_name: "Invalid Email Seller",
  } satisfies ISellerAuthRegisterRequest;

  // 2. The API should throw a validation/type error
  await TestValidator.error("Should return validation error for invalid email")(
    () => api.functional.auth.seller.register.signUp(connection, { body: invalidInput }),
  );

  // 3. (Optional) Further validation can include querying for the account, but is omitted if no search/read API exists for sellers by email.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";

/**
 * E2E test for seller registration required field validation.
 *
 * This test verifies that the POST /auth/seller/register endpoint enforces all required fields. It attempts to register a new seller with fully valid data to demonstrate a successful flow, but intentionally omitting required fields for negative testing cannot be implemented in TypeScript without violating type safety (and is forbidden by project guidelines).
 *
 * Steps:
 * 1. Prepare a valid seller registration data object (all four required fields).
 * 2. Call the registration API and validate success.
 * 3. (Not implementable) Testing registration with missing required fields would require type bypassing, which is not allowed.
 *
 * This test only demonstrates the working happy-path. Compiler restrictions in strict TypeScript prevent negative-case automation for missing required fields.
 */
export async function test_api_seller_registration_missing_required_fields(connection: api.IConnection) {
  // 1. Prepare valid registration data for a new seller
  const request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    business_registration_number: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
  } satisfies ISellerAuthRegisterRequest;

  // 2. Call registration API and validate response
  const output = await api.functional.auth.seller.register.signUp(connection, { body: request });
  typia.assert(output);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";
import type { ISellerAuthLoginRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthLoginRequest";
import type { ISellerAuthTokenResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthTokenResponse";

/**
 * Validate seller login with both correct and incorrect credentials.
 *
 * This E2E test function verifies the authentication logic for seller accounts. It follows these steps:
 *
 * 1. Register a new seller via the sign-up endpoint, ensuring all required onboarding/business info is provided and extract the resulting email, password, and unique registration number.
 * 2. Attempt to log in with the correct credentials (email, password) and confirm that a JWT token is returned by the login endpoint, ensuring all token fields are present and valid.
 * 3. Attempt to log in again with the correct email but an incorrect password, and confirm that the API rejects the login with an authentication error (must throw or signal auth failure).
 *
 * Business logic requires email to be unique, password to meet security requirements, and new sellers to be able to immediately log in. Failure scenario ensures no access is granted with incorrect password, matching legal/compliance expectations and securing seller accounts.
 */
export async function test_api_seller_login_success_and_incorrect_password(connection: api.IConnection) {
  // 1. Register a new seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = "ValidPassword123!";
  const businessRegNum: string = RandomGenerator.alphaNumeric(10);
  const displayName: string = RandomGenerator.name();

  const registration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password,
      business_registration_number: businessRegNum,
      display_name: displayName,
