/**
 * Validates the password change functionality for administrator accounts.
 *
 * This test ensures that an administrator can successfully change their password while authenticated, and verifies both the success and security aspects of the operation.
 *
 * Steps:
 * 1. Register a new administrator account (generating both credentials and an initial login token)
 * 2. Authenticate the administrator explicitly to confirm account works and to establish a session
 * 3. Change the password using the current (correct) password and a new strong password
 * 4. Attempt to log in using the new password (should Succeed)
 * 5. Attempt to log in using the old password (should Fail)
 */
export async function test_api_administrator_change_password_success(connection: api.IConnection) {
  // 1. Register a new administrator account
  const admin_email = typia.random<string & tags.Format<"email">>();
  const admin_display_name = RandomGenerator.alphaNumeric(8);
  const admin_password = RandomGenerator.alphaNumeric(16);
  const admin_role = "superadmin";
  const admin_status = "active";
  // Passwords stored as hashes. For test we use plain text as "hash", simulating valid credentials.
  const admin_password_hash = admin_password;
  const admin: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: admin_email,
      password_hash: admin_password_hash,
      display_name: admin_display_name,
      status: admin_status,
      role: admin_role,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);

  // 2. Explicitly authenticate the administrator (login)
  const session: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: admin_email,
      password_hash: admin_password,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(session);
  // Set Authorization for password change
  connection.headers = {
    ...connection.headers,
    ...session.setHeaders,
  };

  // 3. Change password (provide correct current one, and a new strong one)
  const new_password = RandomGenerator.alphaNumeric(20);
  const profile: IAdministrator.IProfile = await api.functional.auth.administrator.password.changePassword(connection, {
    body: {
      current_password: admin_password,
      new_password,
    } satisfies IAdministrator.IChangePassword,
  });
  typia.assert(profile);
  // Confirm profile data matches original admin id and email
  TestValidator.equals("admin id after password change")(profile.id)(admin.id);
  TestValidator.equals("admin email after password change")(profile.email)(admin.email);

  // 4. Log in with new password (should succeed)
  const sessionNew: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: admin_email,
      password_hash: new_password,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(sessionNew);

  // 5. Log in with old password (should fail)
  await TestValidator.error("login with old password should fail")(async () => {
    await api.functional.auth.administrator.login.signIn(connection, {
      body: {
        email: admin_email,
        password_hash: admin_password,
      } satisfies IAdministrator.ILogin,
    });
  });
}

