  TestValidator.equals("login email matches")(login.email)(adminEmail);
  TestValidator.equals("login display_name matches")(login.display_name)(displayName);

  // 3. Attempt to change password using the WRONG current password
  const wrongCurrentPassword: string = RandomGenerator.alphaNumeric(32); // not the original hash
  const desiredNewPassword: string = RandomGenerator.alphaNumeric(32);
  await TestValidator.error("should fail with wrong current password")(async () => {
    await api.functional.auth.administrator.password.changePassword(connection, {
      body: {
        current_password: wrongCurrentPassword,
        new_password: desiredNewPassword,
      } satisfies IAdministrator.IChangePassword,
    });
  });

  // 4. Re-authenticate using the original credentials to confirm no change
  const relogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(relogin);
  TestValidator.equals("can still login after failed pwd change")(relogin.email)(adminEmail);
  TestValidator.equals("display_name still matches")(relogin.display_name)(displayName);
}

