import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IPageIShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validates advanced search, filter, and pagination for the attachment management API accessible to administrators.
 *
 * Business context:
 * - Attachments may include sensitive evidence, legal/compliance docs, and operational assets, which require correct ACL, legal hold, and business domain logic.
 * - Only authenticated administrators (e.g., superadmin) can use advanced search; authorization is paramount.
 *
 * Test steps:
 * 1. Register a new administrator, login, set Authorization header.
 * 2. Upload a diversified set of attachments (mix of legal hold, business domains, and filenames).
 * 3. As admin, search/filter:
 *    a. Verify basic pagination and result count.
 *    b. Exact/partial filename match semantics.
 *    c. Filter by uploader (admin id) & consistency.
 *    d. Filter for legal hold files, ensure only those returned.
 *    e. Filter by business domain.
 *    f. Query with non-existent filename, expect empty data.
 *    g. Confirm returned files are always permitted for the "superadmin".
 */
export async function test_api_attachment_search_success_filter_pagination_access_control(connection: api.IConnection) {
  // 1. Register administrator (who will be used as attachment uploader)
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    status: "active",
    role: "superadmin",
  } satisfies IAdministrator.ICreate;
  const register = await api.functional.auth.administrator.register.signUp(connection, { body: adminInput });
  typia.assert(register);
  connection.headers = { ...(connection.headers ?? {}), ...register.setHeaders };

  // 2. Upload a diverse set of attachments
  const adminId = register.id;
  const attachments: IShoppingMallAiAttachment[] = [];
  const sampleParams = [
    {
      filename: "invoice_A_001.pdf",
      business_domain: "invoice",
      retention_policy_code: "standard",
      legal_hold: false,
    },
    {
      filename: "product_image_main.png",
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
    },
    {
      filename: "legal_evidence_100.docx",
      business_domain: "evidence",
      retention_policy_code: "evidence",
      legal_hold: true,
    },
    {
      filename: "compliance_2021.xlsx",
      business_domain: "compliance_doc",
      retention_policy_code: "evidence",
      legal_hold: true,
    },
  ];
  for (const params of sampleParams) {
    const output = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
      body: {
        uploaded_by_id: adminId,
        filename: params.filename,
        mime_type: "application/octet-stream",
        file_uri: `https://mock.cdn/attachments/${RandomGenerator.alphaNumeric(10)}`,
        file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1024> & tags.Maximum<32768>>(),
        business_domain: params.business_domain,
        retention_policy_code: params.retention_policy_code,
        legal_hold: params.legal_hold,
        access_acl: JSON.stringify({ allowed_roles: ["superadmin"] }),
      } satisfies IShoppingMallAiAttachment.ICreate,
    });
    typia.assert(output);
    attachments.push(output);
  }

  // Get non-legal/ legal_hold attachments for filter tests
  const [nonLegalAttachment] = attachments.filter(a => !a.legal_hold);
  const [legalAttachment] = attachments.filter(a => a.legal_hold);

  // 3.a. Pagination test: get first page (limit 2)
  let result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(result);
  TestValidator.equals("page size matches or is capped")(result.data.length)(Math.min(attachments.length, 2));
  TestValidator.equals("pagination: current=1")(result.pagination.current)(1);
  TestValidator.equals("pagination: correct limit")(result.pagination.limit)(2);

  // 3.b. Exact filename match
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 5, filename: sampleParams[0].filename },
  });
  typia.assert(result);
  TestValidator.equals("filename exact search")(result.data.length)(1);
  TestValidator.equals("filename exact match")(result.data[0].filename)(sampleParams[0].filename);

  // 3.b. Partial filename match
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, filename: "invoice" },
  });
  typia.assert(result);
  TestValidator.predicate("partial filename search includes invoice_A_001.pdf")(result.data.some(a => a.filename.includes("invoice")));

  // 3.c. Uploader id filter
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, uploader_id: adminId },
  });
  typia.assert(result);
  TestValidator.equals("all results: uploaded_by administrator")(result.data.every(a => a.uploaded_by_id === adminId))(true);

  // 3.d. Legal hold filter
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, legal_hold: true },
  });
  typia.assert(result);
  TestValidator.equals("all results: legal_hold is true")(result.data.every(a => a.legal_hold))(true);
  TestValidator.predicate("legal_hold: expected file present")(result.data.some(a => a.filename === legalAttachment.filename));

  // 3.e. Business domain filter ("invoice")
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, business_domain: "invoice" },
  });
  typia.assert(result);
  TestValidator.predicate("all business_domain: invoice")(result.data.every(a => a.business_domain === "invoice"));

  // 3.f. Non-existent filename filter - expect empty data
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, filename: "non_existent_test_file_xyz" },
  });
  typia.assert(result);
  TestValidator.equals("no matches for non-existent filename")(result.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IPageIShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";
import type { ISellerAuthLoginRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthLoginRequest";
import type { ISellerAuthTokenResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthTokenResponse";

/**
 * Validate that seller users (non-administrator roles) are denied access to the administrator attachment search endpoint.
 *
 * Business context:
 * The /shoppingMallAi/administrator/attachments endpoint allows searching and filtering of all file attachments, but is explicitly restricted to users with administrator privileges only. This endpoint provides access to sensitive business files and compliance information; thus, sellers and customers must be forbidden from accessing it. All unauthorized access attempts should be denied, ideally with logging for security audit, and no underlying attachment information may be returned to the unauthorized user.
 *
 * Test Workflow:
 * 1. Register a new seller account.
 * 2. Log in as the seller, receive a JWT token.
 * 3. Attempt to access the PATCH /shoppingMallAi/administrator/attachments endpoint using the logged-in seller credentials, with a typical attachment search query (randomized valid search input).
 * 4. Validate that the API call fails with an error (e.g., 403 Forbidden or 401 Unauthorized).
 * 5. Confirm that no IPageIShoppingMallAiAttachment.ISummary result is returned on error.
 * 6. (Optional, out of scope for e2e) Security audit logging is not directly testable here, but the failure must be consistent and no data should leak.
 */
export async function test_api_attachment_search_unauthorized_user_access_denied(connection: api.IConnection) {
  // 1. Register a new seller account.
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "testPassword123!";
  const registerOutput = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_registration_number: typia.random<string>(),
      display_name: RandomGenerator.name(),
    } satisfies ISellerAuthRegisterRequest,
  });
  typia.assert(registerOutput);

  // 2. Log in as the seller and receive a JWT token.
  const loginOutput = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuthLoginRequest,
  });
  typia.assert(loginOutput);
  // Set the Authorization header manually if needed, but usually it is managed by the SDK after login
  connection.headers = {
    ...(connection.headers ?? {}),
    Authorization: `Bearer ${loginOutput.access_token}`,
  };

  // 3. Attempt administrative search as seller, expecting failure.
  await TestValidator.error("seller should not access admin attachment search")(async () => {
    await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
      body: {
        page: 1,
        limit: 10,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IPageIShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate that the attachment search endpoint correctly rejects and blocks illegal or malformed search parameters.
 *
 * This test ensures robust input validation for risk-prone filter fields and confirms that the system enforces strict business and technical rules for attachment search, upholding both data privacy and API contract commitments.
 *
 * Steps:
 * 1. Register a new administrator account (to satisfy all administrator authentication requirements for the endpoint).
 * 2. Log in as the newly created administrator and use the returned Authorization header for all protected requests.
 * 3. Construct and send patch requests with illegal or malformed filters:
 *   - Include a property that is not defined in IShoppingMallAiAttachment.IRequest (e.g., "undefined_field").
 *   - Send illegal formats for boolean fields (e.g., pass a string for the "legal_hold" field).
 *   - Provide a pagination value (page or limit) that is out of the allowed range (e.g., 0 or over 100 for limit).
 * 4. For each invalid request, assert that a validation error is thrown and that no sensitive attachment data is leaked.
 * 5. Confirm that only validation errors are returned as expected and the API does not process or leak records on malformed request bodies.
 */
export async function test_api_attachment_search_illegal_filter_error(
  connection: api.IConnection,
) {
  // 1. Register a new administrator account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const password_hash: string = RandomGenerator.alphabets(12);
  const display_name: string = RandomGenerator.name();
  const status = "active";
  const role = "superadmin";
  const signUp = await api.functional.auth.administrator.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password_hash,
        display_name,
        status,
        role,
      },
    },
  );
  typia.assert(signUp);
  // Set Authorization for subsequent calls
  connection.headers = { ...connection.headers, ...signUp.setHeaders };

  // 2. Log in as administrator (explicit authentication renewal)
  const signIn = await api.functional.auth.administrator.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password_hash,
      },
    },
  );
  typia.assert(signIn);
  connection.headers = { ...connection.headers, ...signIn.setHeaders };

  // 3. Attempt illegal/malformed filter requests and validate failures

  // 3.1. Unknown field (should trigger validation error)
  await TestValidator.error("unknown filter field should fail")(() =>
    api.functional.shoppingMallAi.administrator.attachments.search(
      connection,
      {
        body: ({
          page: 1,
          limit: 10,
          undefined_field: "illegal",
        } as unknown) as IShoppingMallAiAttachment.IRequest,
      },
    ),
  );

  // 3.2. Illegal boolean value for "legal_hold"
  await TestValidator.error("illegal boolean value in legal_hold should fail")(
    () =>
      api.functional.shoppingMallAi.administrator.attachments.search(
        connection,
        {
          body: ({
            page: 1,
            limit: 10,
            legal_hold: "not_a_boolean",
          } as unknown) as IShoppingMallAiAttachment.IRequest,
        },
      ),
  );

  // 3.3. Pagination: "limit" below minimum
  await TestValidator.error("limit below min should fail")(() =>
    api.functional.shoppingMallAi.administrator.attachments.search(
      connection,
      {
        body: {
          page: 1,
          limit: 0, // min is 1
        },
      },
    ),
  );

  // 3.4. Pagination: "limit" above maximum
  await TestValidator.error("limit above max should fail")(() =>
    api.functional.shoppingMallAi.administrator.attachments.search(
      connection,
      {
        body: {
          page: 1,
          limit: 101, // max is 100
        },
      },
    ),
  );

  // 3.5. Pagination: "page" below minimum
  await TestValidator.error("page below min should fail")(() =>
    api.functional.shoppingMallAi.administrator.attachments.search(
      connection,
      {
        body: {
          page: 0, // min is 1
          limit: 10,
        },
      },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate the successful creation of metadata for a new attachment by an authenticated administrator.
 *
 * This test covers the following business steps:
 * 1. Register a new administrator with unique credentials.
 * 2. Authenticate (login) as the administrator to obtain a valid access token.
 * 3. As an authenticated administrator, create a new attachment metadata record specifying all business, compliance, and control fields:
 *    - filename, mimetype, file_uri, file_size
 *    - business_domain, retention_policy_code
 *    - legal_hold, access_acl
 * 4. Verify that response includes stored metadata fields, legal/compliance flags, ACL, business domain, retention policy, and user context. Check that generated audit fields (created_at, updated_at, uploaded_by_id) are populated and correct.
 * 5. Confirm that administrator context was used for assignment of uploaded_by_id.
 */
export async function test_api_attachment_create_success_and_compliance(
  connection: api.IConnection,
) {
  // 1. Register a new administrator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(12);
  const displayName: string = RandomGenerator.name();
  const adminRegister = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: password,
      display_name: displayName,
      status: "active",
      role: "superadmin",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(adminRegister);
  const adminId: string = adminRegister.id;

  // 2. Login as administrator (to set authentication context)
  const adminLogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: password,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(adminLogin);
  // Login sets JWT/Authorization in connection.headers automatically

  // 3. Create a new attachment as admin
  const attachmentInput: IShoppingMallAiAttachment.ICreate = {
    // uploaded_by_id is ignored from input, set by backend/security context; still must be provided in type, so use arbitrary uuid
    uploaded_by_id: adminId,
    filename: RandomGenerator.alphaNumeric(10) + ".pdf",
    mime_type: "application/pdf",
    file_uri: "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16) + ".pdf",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<10485760>>(),
    business_domain: "evidence",
    retention_policy_code: "standard",
    legal_hold: true,
    access_acl: JSON.stringify({ allow: ["administrator", "reviewer"] }),
  };

  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentInput,
  });
  typia.assert(attachment);

  // 4. Validate returned fields and compliance context
  TestValidator.equals("filename matches")(attachment.filename)(attachmentInput.filename);
  TestValidator.equals("mime_type matches")(attachment.mime_type)(attachmentInput.mime_type);
  TestValidator.equals("file_uri matches")(attachment.file_uri)(attachmentInput.file_uri);
  TestValidator.equals("file_size matches")(attachment.file_size)(attachmentInput.file_size);
  TestValidator.equals("business_domain matches")(attachment.business_domain)(attachmentInput.business_domain);
  TestValidator.equals("retention_policy_code matches")(attachment.retention_policy_code)(attachmentInput.retention_policy_code);
  TestValidator.equals("legal_hold matches")(attachment.legal_hold)(attachmentInput.legal_hold);
  TestValidator.equals("access_acl matches")(attachment.access_acl)(attachmentInput.access_acl);
  // Confirm audit fields are present
  TestValidator.predicate("created_at is populated")(!!attachment.created_at);
  TestValidator.predicate("updated_at is populated")(!!attachment.updated_at);
  // uploaded_by_id is server-populated and should match authenticated admin
  TestValidator.equals("uploaded_by_id is administrator")(attachment.uploaded_by_id)(adminId);
  // deleted should default to false for new records
  TestValidator.equals("deleted is false")(attachment.deleted)(false);
  // deleted_at should be null or undefined for new attachment
  TestValidator.equals("deleted_at unset")(attachment.deleted_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * 관리자 첨부파일 등록 실패 시나리오를 검증합니다.
 *
 * 관리자 계정이 첨부파일을 등록할 때 다음 실패 상황을 검증합니다:
 *   - 사용자별/도메인별 첨부파일 개수(쿼터) 초과 시 첨부 등록이 거부되는지
 *   - 금지된 파일 타입 또는 비허용 business_domain 등 법적·비즈니스 규칙 위반 시 등록이 거부되는지
 *
 * [테스트 절차]
 * 1. 테스트용 관리자 계정을 생성합니다.
 * 2. 생성된 관리자 계정으로 로그인하여 인증 토큰을 확보합니다.
 * 3. 정상 첨부파일 등록으로 쿼터를 채웁니다(1회 등록 가정 후 즉시 초과 시나리오 진입).
 * 4. 동일 관리자 정보로 첨부파일을 한 번 더 등록(즉, 쿼터 초과) 시도를 하고 정책에 의해 거부되는지 검증합니다.
 * 5. business_domain이나 mime_type 같은 필드에 명확히 허용되지 않는 값을 지정해 법적/비즈니스 위반 시도를 하고, 등록이 거부되는지 검증합니다.
 */
export async function test_api_attachment_create_exceeds_quota_or_legal_violation(
  connection: api.IConnection,
) {
  // 1. 테스트용 관리자 계정 생성
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "$2b$10$abcdefghijklmnopqrstuv12345678901234"; // bcrypt 예시 해시
  const adminRegister = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: "테스트관리자",
      status: "active",
      role: "superadmin",
    },
  });
  typia.assert(adminRegister);

  // 2. 관리자 계정으로 로그인하여 인증 정보 취득
  const adminLogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    },
  });
  typia.assert(adminLogin);
  // 인증 토큰 헤더 적용
  connection.headers = {
    ...connection.headers,
    ...adminLogin.setHeaders,
  };

  // 3. 첨부파일을 정상 등록(쿼터 소진 가정)
  const attachmentBase = {
    uploaded_by_id: adminLogin.id,
    filename: "normal.pdf",
    mime_type: "application/pdf",
    file_uri: "https://cdn.example.com/file1.pdf",
    file_size: 512 * 1024, // 512KB
    business_domain: "invoice",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: '{"role":"superadmin"}',
  };
  const firstAttachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentBase,
  });
  typia.assert(firstAttachment);

  // 4. 동일 관리자/도메인으로 추가 첨부 등록(쿼터 초과) → 실패 검증
  TestValidator.error("첨부파일 쿼터 초과 등록은 실패해야 함")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
        body: {
          ...attachmentBase,
          filename: "another.pdf",
          file_uri: "https://cdn.example.com/another.pdf",
        },
      });
    },
  );

  // 5. 비허용 business_domain/mime_type 등 정책 위반 데이터 등록 시도 → 실패 검증
  TestValidator.error("금지된 business_domain이나 mime_type 등록은 실패해야 함")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
        body: {
          ...attachmentBase,
          filename: "evidence.exe",
          mime_type: "evil/illegal",
          business_domain: "forbidden_domain",
          file_uri: "https://cdn.example.com/evidence.exe",
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";
import type { ISellerAuthLoginRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthLoginRequest";
import type { ISellerAuthTokenResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthTokenResponse";

/**
 * Validate seller-uploaded attachment record creation and ACL enforcement.
 *
 * Business context:
 * Attachments (file metadata and control records) in the AI-powered shopping mall must be created only by authenticated actors via the correct role-associated APIs. Seller-uploaded attachments serve purposes such as product images, invoices, compliance documents, etc., and must only be tagged for business domains accessible by the seller role. The backend must always enforce:
 *   - Only the authenticated user is mapped as the uploader (uploaded_by_id is context-assigned, ignores client-supplied values)
 *   - Seller can only register attachment metadata in permitted business domains
 *   - Retention and legal/compliance flags are enforced according to business logic
 *   - Attachment ACL (access_acl) is persisted as requested for domain-legal cases
 *
 * Steps:
 * 1. Register a new seller via the onboarding API, capturing a valid email/password and business number
 * 2. Authenticate as that seller (login) to obtain JWT/Bearer token for attachment creation
 * 3. Attempt to create an AI attachment record (not physical upload, just metadata) using the /shoppingMallAi/seller/attachments endpoint.
 *    - Provide legal/realistic values for all fields except uploaded_by_id (which should be ignored by backend)
 * 4. Assert:
 *    - The attachment's uploaded_by_id matches the seller account
 *    - business_domain and retention_policy_code are valid for sellers
 *    - Compliance flags (legal_hold, deleted) are correctly stored
 *    - ACL and file metadata are persisted exactly as sent
 *    - Audit timestamps and id fields are assigned
 * 5. Attempt to create an attachment using a business domain the seller role is not allowed to use (e.g., an administrator-only domain) and verify error/denial
 */
export async function test_api_attachment_create_by_seller_success_acl_enforcement(connection: api.IConnection) {
  // 1. Register seller
  const email = typia.random<string & tags.Format<"email">>();
  const password = "SellerTestPassword1!";
  const businessRegNum = RandomGenerator.alphaNumeric(12);
  const displayName = RandomGenerator.name();
  const sellerRegisterResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password,
      business_registration_number: businessRegNum,
      display_name: displayName,
    },
  });
  typia.assert(sellerRegisterResp);
  const sellerId = sellerRegisterResp.seller.id;

  // 2. Authenticate as seller
  const sellerLoginResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(sellerLoginResp);
  connection.headers = {
    ...(connection.headers ?? {}),
    Authorization: `Bearer ${sellerLoginResp.access_token}`,
  };

  // 3. Create an attachment within allowed domain
  const legalAttachmentInput = {
    // uploaded_by_id intentionally incorrect - must be ignored
    uploaded_by_id: typia.random<string & tags.Format<"uuid">>(),
    filename: "manual_product_photo.jpeg",
    mime_type: "image/jpeg",
    file_uri: "https://cdn.example.com/ai-assets/product123/photo.jpeg",
    file_size: 1048576,
    business_domain: "product_image",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: '{"roles":["seller"]}',
  } satisfies IShoppingMallAiAttachment.ICreate;
  const attachmentResp = await api.functional.shoppingMallAi.seller.attachments.create(connection, {
    body: legalAttachmentInput,
  });
  typia.assert(attachmentResp);
  TestValidator.equals("seller maps as uploaded_by_id")(attachmentResp.uploaded_by_id)(sellerId);
  TestValidator.equals("business_domain saved")(attachmentResp.business_domain)(legalAttachmentInput.business_domain);
  TestValidator.equals("retention_policy_code saved")(attachmentResp.retention_policy_code)(legalAttachmentInput.retention_policy_code);
  TestValidator.equals("filename saved")(attachmentResp.filename)(legalAttachmentInput.filename);
  TestValidator.equals("mime_type saved")(attachmentResp.mime_type)(legalAttachmentInput.mime_type);
  TestValidator.equals("file_uri saved")(attachmentResp.file_uri)(legalAttachmentInput.file_uri);
  TestValidator.equals("file_size saved")(attachmentResp.file_size)(legalAttachmentInput.file_size);
  TestValidator.equals("legal_hold saved")(attachmentResp.legal_hold)(legalAttachmentInput.legal_hold);
  TestValidator.equals("access_acl saved")(attachmentResp.access_acl)(legalAttachmentInput.access_acl);
  TestValidator.predicate("created non-empty id")(typeof attachmentResp.id === "string" && attachmentResp.id.length > 0);
  TestValidator.predicate("created_at")(typeof attachmentResp.created_at === "string" && attachmentResp.created_at.length > 0);
  TestValidator.predicate("updated_at")(typeof attachmentResp.updated_at === "string" && attachmentResp.updated_at.length > 0);

  // 4. Create attachment with forbidden domain
  const forbiddenInput = {
    ...legalAttachmentInput,
    business_domain: "compliance_admin_only",
  } satisfies IShoppingMallAiAttachment.ICreate;
  await TestValidator.error("seller forbidden from admin domain")(
    async () => {
      await api.functional.shoppingMallAi.seller.attachments.create(connection, {
        body: forbiddenInput,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";
import type { ISellerAuthLoginRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthLoginRequest";
import type { ISellerAuthTokenResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthTokenResponse";

/**
 * Validate that a seller cannot register attachments for restricted or compliance-only business domains,
 * and cannot set legal hold flags that are disallowed for sellers.
 *
 * This test ensures strict enforcement of domain separation and compliance rules for seller attachment registration in the AI shopping mall:
 *
 * 1. Register a new seller and authenticate as that seller.
 * 2. Attempt to POST an attachment with a business_domain value that is known to be restricted (such as 'compliance_doc' or 'legal_evidence').
 * 3. Attempt to POST an attachment with legal_hold: true (which is not allowed for sellers).
 * 4. For both cases, verify that the API correctly rejects the operation by throwing an error.
 */
export async function test_api_attachment_create_by_seller_forbidden_domain_failure(
  connection: api.IConnection,
) {
  // 1. Register a new seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const registrationNumber = RandomGenerator.alphabets(10);
  const password = "TestPassword123!";
  await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: password,
      business_registration_number: registrationNumber,
      display_name: RandomGenerator.name(),
    },
  });

  // 2. Authenticate as the new seller
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: password,
    },
  });

  // 3. Attempt to register an attachment for a restricted business_domain
  //    (Assuming 'compliance_doc' and 'legal_evidence' are forbidden for sellers)
  const forbiddenDomains = ["compliance_doc", "legal_evidence"];
  for (const business_domain of forbiddenDomains) {
    await TestValidator.error(
      `seller cannot register attachments in forbidden domain: ${business_domain}`,
    )(async () => {
      await api.functional.shoppingMallAi.seller.attachments.create(connection, {
        body: {
          // uploaded_by_id will be ignored by backend - backend uses security context
          uploaded_by_id: typia.random<string & tags.Format<"uuid">>(),
          filename: "restricted.pdf",
          mime_type: "application/pdf",
          file_uri: "https://cdn.example.com/attachments/restricted.pdf",
          file_size: 1024,
          business_domain,
          retention_policy_code: "evidence",
          legal_hold: false,
          access_acl: "{}",
        },
      });
    });
  }

  // 4. Attempt to register an attachment with legal_hold: true (not allowed for sellers)
  await TestValidator.error("seller cannot set legal_hold to true")(async () => {
    await api.functional.shoppingMallAi.seller.attachments.create(connection, {
      body: {
        uploaded_by_id: typia.random<string & tags.Format<"uuid">>(),
        filename: "invoice.pdf",
        mime_type: "application/pdf",
        file_uri: "https://cdn.example.com/attachments/invoice.pdf",
        file_size: 2048,
        business_domain: "invoice",
        retention_policy_code: "evidence",
        legal_hold: true,
        access_acl: "{}",
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate successful and failure flows for administrator updating attachment metadata and ACL, including compliance and legal hold restrictions.
 *
 * This test covers:
 * - Normal editable updates (filename, retention_policy_code, access_acl) for a standard attachment.
 * - Attempts to edit immutable/protected fields (should be rejected or impossible by schema).
 * - Legal hold scenario: Only permitted fields may be updated, restricted compliance fields remain locked.
 *
 * Test Steps:
 * 1. Register a new administrator (ensuring unique, valid credentials and proper role).
 * 2. Login as administrator to obtain session Authorization.
 * 3. Create two attachments:
 *    - (A) Normal (no legal hold).
 *    - (B) Under legal hold (used for negative/restricted field tests).
 * 4. Update mutable fields of Attachment A and verify changes.
 * 5. Attempt to update forbidden immutable/protected fields for A (should be impossible or rejected by backend). 
 * 6. For Attachment B (legal hold), update permitted fields and attempt forbidden changes (should be denied).
 */
export async function test_api_attachment_update_metadata_and_acl_success(
  connection: api.IConnection,
) {
  // 1. Register new administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const displayName = RandomGenerator.name();
  const adminStatus = "active";
  const adminRole = "superadmin";

  const admin = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword, // In test, treat password as hash for dev/test infra
      display_name: displayName,
      status: adminStatus,
      role: adminRole,
    },
  });
  typia.assert(admin);
  connection.headers = {
    ...connection.headers,
    ...(admin.setHeaders ?? {}),
  };

  // 2. Login as administrator, ensuring session/cookie/header set
  const login = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    },
  });
  typia.assert(login);
  connection.headers = {
    ...connection.headers,
    ...(login.setHeaders ?? {}),
  };

  // 3. Create attachments: A (normal), B (legal hold)
  const uploaderId = login.id;
  const baseAttachment = {
    uploaded_by_id: uploaderId,
    filename: "invoice_20250815.pdf",
    mime_type: "application/pdf",
    file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(16)}.pdf`,
    file_size: 204800,
    business_domain: "invoice",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: JSON.stringify({ admins: [login.id], viewers: [] }),
  };
  const attachmentA = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: { ...baseAttachment },
  });
  typia.assert(attachmentA);
  const attachmentB = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      ...baseAttachment,
      filename: "evidence_locked_20250815.jpg",
      mime_type: "image/jpeg",
      file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(16)}.jpg`,
      business_domain: "evidence",
      retention_policy_code: "evidence",
      legal_hold: true,
      uploaded_by_id: uploaderId, // Ensure required by DTO
    },
  });
  typia.assert(attachmentB);

  // 4. Update allowed mutable fields on Attachment A
  const updatedA = await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
    attachmentId: attachmentA.id,
    body: {
      filename: "invoice_updated_20250815.pdf",
      retention_policy_code: "extended",
      access_acl: JSON.stringify({ admins: [admin.id], viewers: ["random_viewer"] }),
    },
  });
  typia.assert(updatedA);
  TestValidator.equals("filename changed")(updatedA.filename)("invoice_updated_20250815.pdf");
  TestValidator.equals("acl changed")(updatedA.access_acl)(JSON.stringify({ admins: [admin.id], viewers: ["random_viewer"] }));
  TestValidator.equals("retention code changed")(updatedA.retention_policy_code)("extended");

  // 5. Attempt to update illegal/immutable fields (not possible by schema, but backend can still return error if attempted)
  await TestValidator.error("updating immutable/protected field fails")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
        attachmentId: attachmentA.id,
        body: {
          filename: "should_not_work.pdf",
        },
      });
    },
  );

  // 6. Legal hold scenario: update allowed fields and attempt forbidden change
  const updatedLegal = await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
    attachmentId: attachmentB.id,
    body: {
      filename: "evidence_title_change_20250815.jpg",
      access_acl: JSON.stringify({ admins: [admin.id], viewers: ["reviewer"] }),
    },
  });
  typia.assert(updatedLegal);
  TestValidator.equals("legal hold filename change")(updatedLegal.filename)("evidence_title_change_20250815.jpg");

  // Try forbidden: turning off legal hold on a locked attachment (should be rejected)
  await TestValidator.error("cannot turn off legal hold while locked")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
        attachmentId: attachmentB.id,
        body: { legal_hold: false },
      });
    },
  );
}

