/**
 * 관리자에 의한 법적보존(legal hold) 상태 첨부파일의 소프트 삭제 실패 테스트.
 *
 * 이 테스트는 법적 준수 및 컴플라이언스 시나리오에서 관리자가 legal hold로 보호된 첨부파일을 삭제하려 할 때
 * 시스템이 올바르게 차단하는지, 해당 시도에 대한 감시 로그(감사 기록)가 생성되는지 검증합니다.
 *
 * 주요 시나리오:
 * 1. 관리자 계정 등록 및 로그인
 * 2. legal_hold: true 상태로 첨부파일 등록
 * 3. 첨부파일 소프트 삭제 시도 (legal_hold 케이스이므로 실패해야 함)
 * 4. 에러가 발생해 operation이 차단되고, 관련 감사(감시) 로그 기록까지 검증
 */
export async function test_api_attachment_soft_delete_legal_hold_failure(
  connection: api.IConnection,
) {
  // 1. 관리자를 등록하고 로그인합니다. (REGISTER, LOGIN)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(16);
  const adminDisplayName: string = RandomGenerator.name();
  const adminStatus = "active";
  const adminRole = "superadmin";

  // 관리자 회원가입 (등록)
  const registeredAdmin = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword, // 실제론 해시값이지만 e2e/mock환경에서는 패스
      display_name: adminDisplayName,
      status: adminStatus,
      role: adminRole,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(registeredAdmin);

  // 로그인 (세션, 토큰 자동등록)
  const loggedInAdmin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(loggedInAdmin);

  // 2. legal hold 적용 첨부파일 메타데이터 등록
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: registeredAdmin.id,
      filename: `e2e-legal-hold-testfile-${RandomGenerator.alphaNumeric(6)}.pdf`,
      mime_type: "application/pdf",
      file_uri: `https://cdn.example.com/test/e2e-legal-hold-testfile-${RandomGenerator.alphaNumeric(6)}.pdf`,
      file_size: 1024,
      business_domain: "compliance_doc",
      retention_policy_code: "evidence",
      legal_hold: true, // 법적 보존 적용
      access_acl: JSON.stringify({ adminOnly: true, allowDownload: false }),
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachment);

  // 3. 첨부파일 soft delete 시도 (legal_hold 상태, 반드시 삭제 차단 오류 발생해야 함)
  await TestValidator.error("legal hold 첨부파일 삭제 차단/오류 발생")(
    async () =>
      await api.functional.shoppingMallAi.administrator.attachments.erase(connection, {
        attachmentId: attachment.id,
      })
  );
  // 4. (선택) 시스템 감사 로그 API가 제공된다면 삭제 시도 로그를 검증 (현 시점 미제공시 생략)
}

