import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachmentVersion";
import type { IPageIShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachmentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validates an administrator can page through the version history of an attachment.
 *
 * Business context: Attachments (files/metadata) are versioned for audit, evidence, and legal compliance reasons. Only authenticated admins can query all version history with pagination and filters. This test ensures correct paginated list of version summaries is returned, with each summary reflecting the version and audit information for the attachment. Also validates authorized access is required.
 *
 * Steps:
 * 1. Register a new administrator with unique credentials and status 'active'.
 * 2. Login as the registered administrator using the same credentials to ensure valid JWT, reflecting session handling.
 * 3. As the administrator, create an attachment with realistic metadata (mimicking file upload bookkeeping).
 * 4. Register multiple versions for the created attachment by POSTing valid version metadata, incrementing/filling version numbers.
 * 5. PATCH the search endpoint for this attachment's versions with pagination (limit/page). Verify:
 *    - The returned page object shows correct pagination (page, limit, data.length).
 *    - Each version summary includes valid id, attachment_id, version_number, file_uri, file_size, diff_comment, created_at, and deleted.
 *    - The data array is ordered by version_number ascending (default or specified sort).
 *    - All returned entries belong to the test attachment.
 *    - The count and data matches the number of POSTed versions.
 * 6. Error: Attempt to search versions without authentication and verify access is denied.
 */
export async function test_api_attachment_version_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const admin: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin"
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);

  // 2. Login (ensure JWT headers stored)
  const login: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login);

  // 3. Create an attachment as admin
  const attachment: IShoppingMallAiAttachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: admin.id,
      filename: RandomGenerator.alphaNumeric(12),
      mime_type: "image/jpeg",
      file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(16)}`,
      file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1000> & tags.Maximum<1000000>>(),
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: JSON.stringify({ admin: [admin.id], roles: [admin.role] })
    } satisfies IShoppingMallAiAttachment.ICreate
  });
  typia.assert(attachment);

  // 4. Register N versions for the attachment
  const versionCount = 5;
  const versions: IShoppingMallAiAttachmentVersion[] = [];
  for (let i = 0; i < versionCount; ++i) {
    const createdVersion: IShoppingMallAiAttachmentVersion = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.createVersion(connection, {
      attachmentId: attachment.id,
      body: {
        modified_by_id: admin.id,
        file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(20)}`,
        file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1000> & tags.Maximum<1000000>>(),
        diff_comment: `Version ${i + 1} - ${RandomGenerator.paragraph()()}`
      } satisfies IShoppingMallAiAttachmentVersion.ICreate
    });
    typia.assert(createdVersion);
    versions.push(createdVersion);
  }

  // 5. Search/paginate versions for this attachment, page 1 (limit 3)
  const searchResult = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.searchVersions(connection, {
    attachmentId: attachment.id,
    body: {
      page: 1,
      limit: 3
    } satisfies IShoppingMallAiAttachmentVersion.IRequest
  });
  typia.assert(searchResult);
  // Pagination meta
  TestValidator.equals("pagination current page")(searchResult.pagination.current)(1);
  TestValidator.equals("pagination limit")(searchResult.pagination.limit)(3);
  // Data shape and linkage
  for (const v of searchResult.data) {
    TestValidator.equals("attachment linkage")(v.attachment_id)(attachment.id);
    TestValidator.predicate("positive version number")(v.version_number > 0);
    TestValidator.predicate("file uri not empty")(!!v.file_uri);
    TestValidator.predicate("file size positive")(v.file_size > 0);
    TestValidator.predicate("created_at ISO8601")(!!v.created_at && !isNaN(Date.parse(v.created_at)));
    TestValidator.predicate("deleted boolean")(typeof v.deleted === "boolean");
  }
  TestValidator.equals("entries are paged correctly")(searchResult.data.length)(Math.min(3, versions.length));
  const sorted = [...searchResult.data].sort((a, b) => a.version_number - b.version_number);
  TestValidator.equals("version_number sorted")(searchResult.data)(sorted);

  // 6. Access denied for unauthenticated call
  const unauthConn = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated version search should be denied")(async () => {
    await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.searchVersions(unauthConn, {
      attachmentId: attachment.id,
      body: {
        page: 1,
        limit: 2
      }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachmentVersion";
import type { IPageIShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachmentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";
