/**
 * Validate that the API correctly returns an error when trying to fetch metadata for a non-existent attachment version.
 *
 * This test ensures sensitive information is not leaked about non-existent or unauthorized attachment versions. The correct behavior is to return a not-found or access error when a random or invalid version ID is used.
 *
 * Steps:
 * 1. Register a new administrator (necessary for the protected endpoint).
 * 2. Log in as the administrator to obtain a valid session/token.
 * 3. Create a new attachment using administrator privileges.
 * 4. Attempt to retrieve details for an attachment version using the correct attachmentId but a random, non-existent attachmentVersionId.
 * 5. Expect and assert that a not-found or error response is thrown (do not allow details leakage).
 */
export async function test_api_attachment_version_details_not_found(connection: api.IConnection) {
  // 1. Register a new administrator
  const passwordHash = "hashedPassword123";
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminRegister = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(adminRegister);

  // 2. Log in as that administrator (ensuring token is set in connection)
  const adminLogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(adminLogin);

  // 3. Create a new attachment (to obtain a valid attachmentId)
  const attachmentCreate = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: adminRegister.id,
      filename: RandomGenerator.alphabets(8) + ".jpg",
      mime_type: "image/jpeg",
      file_uri: `https://cdn.example.com/files/` + RandomGenerator.alphabets(8),
      file_size: 204800,
      business_domain: "test_domain",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: JSON.stringify({ admins: [adminRegister.id] }),
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachmentCreate);

  // 4. Attempt to fetch a non-existent version; should yield an error
  const randomVersionId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Should error when an invalid attachmentVersionId is given")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.atVersion(connection, {
        attachmentId: attachmentCreate.id,
        attachmentVersionId: randomVersionId,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachmentVersion";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate administrator's ability to register a new version for an attachment and audit compliance information.
 *
 * Business context: Administrators in the AI-powered shopping mall system must be able to not only create attachment metadata (such as compliance documents, catalog images, or evidence) but also register new versions for those attachments while recording a full audit/compliance trail. The sequence tests necessary business workflow as well as regulatory audit trace requirements: proper actor assignment, version incrementing, and audit difference reason capture.
 *
 * Steps:
 * 1. Register a new administrator (with unique random email, password hash, display_name, active status, and a plausible role)
 * 2. Log in as that administrator to obtain JWT credentials for subsequent auth
 * 3. Create an attachment (simulate business context with random but valid metadata)
 * 4. Register a new version for the attachment using the administrator's credentials and simulate a compliance change scenario (e.g., diff_comment is set to 'Cropped for privacy')
 * 5. Validate that the new version has correct modified_by_id (should match the admin user), correct attachment association, version_number is incremented (1 for first version), audit fields are correct, and that core file properties are as expected. Also, validate that an explicit diff_comment is reflected in the version record.
 */
export async function test_api_create_attachment_version_success(connection: api.IConnection) {
  // 1. Register a new administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash = RandomGenerator.alphaNumeric(15);
  const adminDisplayName = RandomGenerator.name();
  const adminStatus = "active";
  const adminRole = "superadmin";

  const admin = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
      display_name: adminDisplayName,
      status: adminStatus,
      role: adminRole,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);

  // 2. Log in as that administrator
  const loginResult = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(loginResult);

  // Update the connection's Authorization token for admin session (simulate client behavior)
  connection.headers = {
    ...connection.headers,
    Authorization: loginResult.setHeaders.Authorization,
  };

  // 3. Create an attachment (admin is uploader; backend MUST use authenticated user as uploaded_by_id)
  const attachmentCreateInput = {
    uploaded_by_id: admin.id, // SDK/back must ignore client value but we provide it for documentation
    filename: RandomGenerator.alphaNumeric(8) + ".pdf",
    mime_type: "application/pdf",
    file_uri: "https://cdn.example.com/files/" + typia.random<string & tags.Format<"uuid">>() + ".pdf",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1024> & tags.Maximum<40960>>(),
    business_domain: "compliance_doc",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: JSON.stringify({ allow: ["superadmin"] }),
  } satisfies IShoppingMallAiAttachment.ICreate;
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentCreateInput,
  });
  typia.assert(attachment);
  TestValidator.equals("admin as uploader")(attachment.uploaded_by_id)(admin.id);
  TestValidator.equals("filename")(attachment.filename)(attachmentCreateInput.filename);
  TestValidator.equals("business domain")(attachment.business_domain)("compliance_doc");

  // 4. Register a new version of the attachment (diff_comment for compliance tracking)
  const versionInput = {
    modified_by_id: admin.id,
    file_uri: "https://cdn.example.com/files/" + typia.random<string & tags.Format<"uuid">>() + "_v2.pdf",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<2048> & tags.Maximum<81920>>(),
    diff_comment: "Cropped for privacy compliance - PII removed",
  } satisfies IShoppingMallAiAttachmentVersion.ICreate;
  const attachmentVersion = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.createVersion(connection, {
    attachmentId: attachment.id,
    body: versionInput,
  });
  typia.assert(attachmentVersion);
  TestValidator.equals("attachment association")(attachmentVersion.attachment_id)(attachment.id);
  TestValidator.equals("modified by admin")(attachmentVersion.modified_by_id)(admin.id);
  TestValidator.equals("diff_comment captured")(attachmentVersion.diff_comment)(versionInput.diff_comment);
  TestValidator.equals("first version number")(attachmentVersion.version_number)(1);
  TestValidator.equals("not deleted")(attachmentVersion.deleted)(false);
  TestValidator.predicate("file URI ends with _v2.pdf")(attachmentVersion.file_uri.endsWith("_v2.pdf"));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachmentVersion";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate system prohibits creating attachment version for deleted attachment (failure path).
 *
 * This test ensures that, after an admin registers, logs in, creates an attachment, and then soft-deletes that attachment, attempts to create a new attachment version for the deleted attachment are rejected by the system for compliance/audit reasons.
 * This is a critical business rules test: soft-deleted (logically deleted) attachments must not permit new versions, as this would violate audit/compliance logics and evidence immutability.
 *
 * Steps:
 * 1. Register an admin with unique email/password_hash/display_name, status 'active', and real role
 * 2. Login as admin (to set JWT for subsequent privileged requests)
 * 3. Create an attachment using the admin session
 * 4. Soft-delete the attachment by id (using privileged admin session)
 * 5. Try to create a new attachment version for the now-soft-deleted attachment.
 *    - This should fail (business error or not found) as no versions may be created for deleted attachments
 * 6. Assert the operation fails (TestValidator.error), i.e., system does NOT permit version appending to deleted attachment
 */
export async function test_api_create_attachment_version_deleted_attachment_failure(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const passwordHash: string = "TestPassword#12345_hash";
  const admin: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin"
    } satisfies IAdministrator.ICreate
  });
  typia.assert(admin);

  // 2. Login as admin (load proper JWT)
  const loginResp = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
