import type { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Successfully update a specific attachment version's metadata by administrator.
 *
 * This test validates the workflow for updating metadata (diff_comment and deleted flag) of an attachment version by an administrator. The process assures creation, authentication, chained resource setup, metadata update, and post-update verification including all relevant audit fields.
 *
 * Workflow:
 * 1. Register a new administrator, acquiring credentials and JWT headers.
 * 2. Login as the new administrator and verify token/headers are issued.
 * 3. Create a new attachment record to act as the parent entity for version creation.
 * 4. Create an attachment version for this attachment with compliant metadata.
 * 5. Update the version's metadata as administrator (e.g., set new diff_comment, change deleted flag).
 * 6. Verify all updatable properties (diff_comment, deleted) were updated successfully and that immutable fields remain unchanged, ensuring proper audit trail behavior.
 */
export async function test_api_update_attachment_version_metadata_success(connection: api.IConnection) {
  // 1. Register administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash = RandomGenerator.alphaNumeric(16); // Simulate hash
  const adminDisplayName = RandomGenerator.name();
  const adminStatus = "active";
  const adminRole = "superadmin";
  const registerResult = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
      display_name: adminDisplayName,
      status: adminStatus,
      role: adminRole,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(registerResult);
  TestValidator.equals("admin email matches")(registerResult.email)(adminEmail);

  // 2. Login as administrator (simulates fresh login/token behavior)
  const loginResult = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(loginResult);
  TestValidator.equals("login email matches")(loginResult.email)(adminEmail);

  // 3. Create an attachment with random metadata
  const attachmentResult = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: registerResult.id, // System should override as current admin
      filename: RandomGenerator.alphaNumeric(12) + ".jpg",
      mime_type: "image/jpeg",
      file_uri: "https://cdn.example.com/" + RandomGenerator.alphaNumeric(16),
      file_size: typia.random<number & tags.Type<"int32">>(),
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: '{"roles":["admin"]}',
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachmentResult);
  TestValidator.equals("attachment uploader matches")(attachmentResult.uploaded_by_id)(registerResult.id);

  // 4. Create a version for this attachment
  const attachmentVersion = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.createVersion(connection, {
    attachmentId: attachmentResult.id,
    body: {
      modified_by_id: registerResult.id,
      file_uri: attachmentResult.file_uri,
      file_size: attachmentResult.file_size,
      diff_comment: "Initial version.",
    } satisfies IShoppingMallAiAttachmentVersion.ICreate,
  });
  typia.assert(attachmentVersion);
  TestValidator.equals("version parent matches")(attachmentVersion.attachment_id)(attachmentResult.id);
  TestValidator.equals("version modifier matches")(attachmentVersion.modified_by_id)(registerResult.id);

  // 5. Update the version metadata (set diff_comment and deleted to true)
  const updatedDiffComment = "Redacted for compliance.";
  const updateDeleted = true;
  const updatedVersion = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.update(connection, {
    attachmentId: attachmentResult.id,
    attachmentVersionId: attachmentVersion.id,
    body: {
      diff_comment: updatedDiffComment,
      deleted: updateDeleted,
    } satisfies IAttachment.AttachmentVersion.IUpdate,
  });
  typia.assert(updatedVersion);

  // 6. Validate all relevant fields were updated and immutable fields remain correct
  TestValidator.equals("updated diff_comment")(updatedVersion.diff_comment)(updatedDiffComment);
  TestValidator.equals("updated deleted flag")(updatedVersion.deleted)(updateDeleted);
  TestValidator.equals("updated version id unchanged")(updatedVersion.id)(attachmentVersion.id);
  TestValidator.equals("updated parent id unchanged")(updatedVersion.attachment_id)(attachmentVersion.attachment_id);
  TestValidator.equals("updated modifier unchanged")(updatedVersion.modified_by_id)(attachmentVersion.modified_by_id);
  TestValidator.equals("version number unchanged")(updatedVersion.version_number)(attachmentVersion.version_number);
  TestValidator.equals("file_uri unchanged")(updatedVersion.file_uri)(attachmentVersion.file_uri);
  TestValidator.equals("file_size unchanged")(updatedVersion.file_size)(attachmentVersion.file_size);
  TestValidator.equals("created_at unchanged")(updatedVersion.created_at)(attachmentVersion.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachmentVersion";
import type { IPageIShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachmentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Test administrator-initiated soft-deletion of an attachment version for compliance and audit.
 *
 * Business context:
 * Administrators must be able to soft-delete file versions for policy or audit purposes—only if not under legal hold or already deleted. Deleted versions are excluded from normal listings but must remain accessible through audit logs. Only admins with proper authority may perform deletion. This process is key to compliance, chain of custody, and evidence handling.
 *
 * Test Steps:
 * 1. Register a new administrator with unique credentials and active status/role.
 * 2. Log in as this admin to obtain authentication, ensuring proper auth context for subsequent API usage.
 * 3. Create an attachment as this admin, supplying valid metadata (mime, filename, uri, size, domain, retention, acl, not legal hold, not deleted).
 * 4. Register a new version for the created attachment, as the same admin (new file uri, diff comment, etc).
 * 5. List all (not-deleted by default) versions of the attachment; find our new version.
 * 6. Soft-delete the version using administrator delete API (only allowed if not legal hold).
 * 7. Verify that:
 *    - The version is excluded from default (not-deleted) version list.
 *    - The version is present when requesting deleted versions for audit.
 *    - Audit trail and soft-delete properties updated accordingly.
 */
export async function test_api_attachment_version_soft_delete_success(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const admin: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin"
    } satisfies IAdministrator.ICreate
  });
  typia.assert(admin);

  // 2. Login as admin (to verify login flow is correct)
  const login: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword
    } satisfies IAdministrator.ILogin
  });
  typia.assert(login);
  connection.headers = { ...connection.headers, ...login.setHeaders };

  // 3. Create attachment
  const attachment: IShoppingMallAiAttachment = await api.functional.shoppingMallAi.administrator.attachments.create(
    connection, {
      body: {
        uploaded_by_id: admin.id,
        filename: RandomGenerator.alphaNumeric(12) + ".jpg",
        mime_type: "image/jpeg",
        file_uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(24)}.jpg`,
        file_size: 153600,
        business_domain: "product_image",
        retention_policy_code: "standard",
        legal_hold: false,
        access_acl: JSON.stringify({ admin: [admin.id] })
      } satisfies IShoppingMallAiAttachment.ICreate
    }
  );
  typia.assert(attachment);
  TestValidator.equals("created_by admin context")(attachment.uploaded_by_id)(admin.id);
  TestValidator.equals("legal_hold is false")(attachment.legal_hold)(false);

  // 4. Create new version for this attachment
  const version: IShoppingMallAiAttachmentVersion = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.createVersion(
    connection, {
      attachmentId: attachment.id,
      body: {
        modified_by_id: admin.id,
        file_uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(24)}.v1.jpg`,
        file_size: 153600,
        diff_comment: "Initial upload"
      } satisfies IShoppingMallAiAttachmentVersion.ICreate
    }
  );
  typia.assert(version);
  TestValidator.equals("version not deleted")(version.deleted)(false);

  // 5. List all non-deleted versions (should include the new version)
  const verPage1 = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.searchVersions(
    connection, {
      attachmentId: attachment.id,
      body: {
        page: 1,
        limit: 10,
        deleted: false
      }
    });
  typia.assert(verPage1);
  const found = verPage1.data.find((v) => v.id === version.id);
  TestValidator.predicate("new version should appear in not-deleted list")(!!found);
  TestValidator.equals("deleted flag is false")(found?.deleted)(false);

  // 6. Soft-delete the version
  await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.erase(
    connection,
    {
      attachmentId: attachment.id,
      attachmentVersionId: version.id
    }
  );
  // No output, just validate via re-listing

  // 7a. Should be gone from non-deleted list
  const verPage2 = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.searchVersions(
    connection, {
      attachmentId: attachment.id,
      body: {
        page: 1,
        limit: 10,
        deleted: false
      }
    });
  typia.assert(verPage2);
  const refind = verPage2.data.find((v) => v.id === version.id);
  TestValidator.equals("version removed from default list")(refind)(undefined);

  // 7b. Should appear in the audit (deleted) view
  const auditPage = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.searchVersions(
    connection, {
      attachmentId: attachment.id,
      body: {
        page: 1,
        limit: 10,
        deleted: true
      }
    });
  typia.assert(auditPage);
  const auditVersion = auditPage.data.find((v) => v.id === version.id);
  TestValidator.predicate("deleted version should appear in audit listing")(!!auditVersion);
  TestValidator.equals("deleted flag is true")(auditVersion?.deleted)(true);
}

