    uploaded_by_id: admin.id,
    filename: RandomGenerator.alphaNumeric(12),
    mime_type: "image/jpeg",
    file_uri: `https://cdn.mall/${RandomGenerator.alphaNumeric(24)}`,
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<10000>>() ,
    business_domain: "evidence",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: "{\"role\":\"admin\"}"
  } satisfies IShoppingMallAiAttachment.ICreate;
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentInput
  });
  typia.assert(attachment);
  TestValidator.equals("attachment.uploaded_by_id matches")(attachment.uploaded_by_id)(admin.id);

  // 4. Create attachment-business link
  const targetDomain = "product";
  const targetId = typia.random<string & tags.Format<"uuid">>();
