  TestValidator.equals("business link attachment_id")(businessLink.attachment_id)(attachment.id);
  TestValidator.equals("business link domain")(businessLink.target_domain)(targetDomain);
  TestValidator.equals("business link target_id")(businessLink.target_id)(targetId);
  TestValidator.equals("business link linked_by_id")(businessLink.linked_by_id)(admin.id);

