 *   5. Register administrator2 (active status/role), representing a separate admin (no domain ownership).
 *   6. Login as administrator2 – activating a new session with separate authorization.
 *   7. Attempt as administrator2 to fetch the business link using both UUIDs (should be rejected, access denied).
 *   8. Verify error occurs – validate that unauthorized access is prevented.
 */
export async function test_api_attachment_business_link_get_unauthorized_access(connection: api.IConnection) {
