  const admin2Password = RandomGenerator.alphaNumeric(16);
  const admin2: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: admin2Email,
      password_hash: admin2Password,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin"
    } satisfies IAdministrator.ICreate
  });
  typia.assert(admin2);

  // 6. Login as administrator2 (separate security context)
  await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: admin2Email,
      password_hash: admin2Password
    } satisfies IAdministrator.ILogin
  });

  // 7. Attempt to fetch the business link as admin2 (should be denied)
  await TestValidator.error("should reject unauthorized admin2 access")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.at(connection, {
        attachmentId: attachment.id,
        attachmentBusinessLinkId: businessLink.id
      });
    }
  );
