    deleted_at: record.deleted_at ? toISOStringSafe(record.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";


/**
 * Register a new attachment's metadata, business domain, and access context after file upload.
 *
 * This endpoint registers a new attachment (file record) in the system. It operates on the shopping_mall_ai_attachments table and creates a metadata entry for a newly uploaded file, capturing all required fields: original filename, mime type, file URI, size, domain, uploader, retention policy code, ACL, and legal/compliance flags.
 *
 * Physical file upload is expected to be handled out-of-band, with this API designed to register metadata and business context after successful storage. The record includes access and retention policies, legal/security flags for compliance, and supports immediate use in downstream business flows (invoices, product images, evidence, etc.).
 *
 * Only authorized users may register attachments. The endpoint also observes duplicate and quota rules, audit logging, and business domain integrity (e.g., images for products must be properly mapped, evidence mapped to reviews/inquiries/orders, etc.).
 *
 * @param props - Properties including the business metadata about the file upload
 * @returns The fully registered attachment entry
 * @throws {Error} When failing to create the attachment due to DB errors or invalid input
 */
export async function post__shoppingMallAi_administrator_attachments(
  props: { body: IShoppingMallAiAttachment.ICreate }
): Promise<IShoppingMallAiAttachment> {
  const { body } = props;

  const now = toISOStringSafe(new Date());
  const id = v4() as string & tags.Format<'uuid'>;

  const created = await MyGlobal.prisma.shopping_mall_ai_attachments.create({
    data: {
      id,
      uploaded_by_id: body.uploaded_by_id,
      filename: body.filename,
      mime_type: body.mime_type,
      file_uri: body.file_uri,
      file_size: body.file_size,
      business_domain: body.business_domain,
      retention_policy_code: body.retention_policy_code,
      legal_hold: body.legal_hold,
      deleted: false,
      access_acl: body.access_acl,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    uploaded_by_id: created.uploaded_by_id,
